package com.delivery.platform.orders.application;
import org.junit.jupiter.api.Test;import java.math.BigDecimal;import static org.assertj.core.api.Assertions.assertThat;
class OrderCalculatorTest {@Test void calculatesBackendOwnedTotals(){var x=OrderCalculator.calculate(new BigDecimal("100"),new BigDecimal("18"),new BigDecimal("10"),new BigDecimal("5"),"PEN");assertThat(x.total()).isEqualByComparingTo("95.00");assertThat(x.currency()).isEqualTo("PEN");}@Test void neverReturnsNegativeTotal(){var x=OrderCalculator.calculate(BigDecimal.TEN,BigDecimal.ZERO,new BigDecimal("30"),BigDecimal.ZERO,"PEN");assertThat(x.total()).isEqualByComparingTo("0.00");}}
